window.AUTH=window.AUTH||{};window.AUTH["07-581"]={"d":"07-581","id":"2008/07-581","n":"14 Penn Plaza LLC v. Pyett","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondents","date":"","url":"https://www.justice.gov/osg/media/216061/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/14-penn-plaza-llc-v-pyett-amicus-merits","n":60}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep556/usrep556247/usrep556247.pdf","tr":true,"items":[{"t":"case","label":"Alexander v. Gardner-Denver Co.","cite":"415 U.S. 36","y":1974,"id":"1973/72-5847","sc":1,"op":19,"ar":2,"sum":"An employee's statutory right to trial de novo under Title VII of the Civil Rights Act of 1964 is not foreclosed by prior submission of his claim to final arbitration under the nondiscrimination clause of a collective-bargaining.agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Air Line Pilots Ass’n v. O’Neill","cite":"499 U.S. 65","y":1991,"id":"1990/89-1493","sc":1,"sum":"After Continental Airlines, Inc., filed a petition for reorganization under Chapter 11 of the Bankruptcy Code, it repudiated its collectivebargaining agreement with petitioner Air Line Pilots Association, International (ALPA). An acrimonious strike ensued, during which Continental hired replacement pilots and reemployed several hundred crossover strikers. Two years into the strike, Continental announced in its …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Air Line Pilots Ass’n, Int’l v. Northwest Airlines, Inc.","cite":"199 F.3d 477","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/199/477/","op":1,"by":{"0":"31"}},{"t":"case","label":"Atchison, Topeka & Santa Fe Ry. v. Buell","cite":"480 U.S. 557","y":1987,"id":"1986/85-1140","sc":1,"op":1,"sum":"Under the Federal Employers' Liability Act (FELA), railroad workers can sue their employers for personal injuries suffered at the hands of the employers or fellow employees. The Railway Labor Act (RLA) provides for the submission of minor labor disputes in the railroad industry to binding arbitration. Respondent, a carman employed by petitioner, filed an FELA suit in Federal District Court, alleging that petitioner …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Barrentine v. Arkansas-Best Freight Sys., Inc.","cite":"450 U.S. 728","y":1981,"id":"1980/79-2006","sc":1,"op":10,"ar":4,"sum":"Petitioners' wage claims under the FLSA are not barred by the prior submission of their grievances to the contractual dispute-resolution procedures.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 9, 13, 14, 29"}},{"t":"case","label":"Bowen v. USPS","cite":"459 U.S. 212","y":1983,"id":"1982/81-525","sc":1,"sum":"Where the District Court's findings, accepted by the Court of Appeals, established that petitioner's damages were caused initially by the USPS's unlawful discharge and were increased by the Union's breach of its duty of fair representation, apportionment of the damages was required. Vaca v. Sipes, 386 U. S. 171.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"532 U.S. 105","y":2001,"id":"2000/99-1379","sc":1,"op":5,"ar":15,"sum":"The Court held that section 1 exemption is confined to transportation workers. \"The wording of [section 1] calls for the application of the maxim ejusdem generis, the statutory canon that 'where general words follow specific words in a statutory enumeration, the general words are construed to embrace only objects similar in nature to those objects enumerated by the preceding specific words,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Coca-Cola Bottling Co. v. Soft Drink & Brewery Workers Union Local 812","cite":"242 F.3d 52","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/242/52/","by":{"0":"23"}},{"t":"case","label":"DelCostello v. International Bhd. of Teamsters","cite":"462 U.S. 151","y":1983,"id":"1982/81-2386","sc":1,"op":1,"sum":"The issue in each of these cases is what statute of limitations applies in an employee suit against an employer and a union, alleging the employer's breach of a collective-bargaining agreement and the union's breach of its duty of fair representation by mishandling the ensuing grievance or arbitration proceedings. United Parcel Service, Inc. v. Mitchell, 451 U. S. 56, held in a similar suit that an employee's claim …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"EEOC v. Waffle House, Inc.","cite":"534 U.S. 279","y":2002,"id":"2001/99-1823","sc":1,"op":5,"ar":3,"sum":"The Court held that the arbitration agreement did not bar the EEOC from pursuing victim-specific judicial relief in an ADA enforcement action. The Court reasoned that the EECO's statutory enforcement powers unambiguously authorized the EEOC to obtain the relief that it sought in its complaint, if it could prove its case against the employer.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Faragher v. City of Boca Raton","cite":"524 U.S. 775","y":1998,"id":"1997/97-282","sc":1,"sum":"The Court held that an employer is vicariously liable under Title VII of the Civil Rights Act of 1964 for actionable discrimination caused by a supervisor.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Gilmer v. Interstate/Johnson Lane Corp.","cite":"500 U.S. 20","y":1991,"id":"1990/90-18","sc":1,"op":24,"ar":15,"sum":"An ADEA claim can be subjected to compulsory arbitration.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Green Tree Fin. Corp.-Ala. v. Randolph","cite":"531 U.S. 79","y":2000,"id":"2000/99-1235","sc":1,"op":1,"sum":"The Court held that an order compelling arbitration pursuant to the parties' agreement is a \"final decision with respect to an arbitration\" within the meaning of the Federal Arbitration Act making it immediately appealable pursuant to the FAA.","sumSrc":"Oyez","by":{"0":"15, 21"}},{"t":"case","label":"International Ass’n of Machinists & Aerospace Workers Local Lodge 2121 v. Goodrich Corp.","cite":"410 F.3d 204","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/410/204/","by":{"0":"22"}},{"t":"case","label":"Lingle v. Norge Div. of Magic Chef, Inc.","cite":"486 U.S. 399","y":1988,"id":"1987/87-259","sc":1,"sum":"Application of petitioner's state tort remedy was not pre-empted by §301. An application of state law is pre-empted by §301 only if such application requires the interpretation of a collective-bargaining agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Livadas v. Bradshaw","cite":"512 U.S. 107","y":1994,"id":"1993/92-1920","sc":1,"op":1,"sum":"California law requires employers to pay all wages due immediately upon an employee's discharge, Labor Code §201; imposes a penalty for refusal to pay promptly, §203; and places responsibility for enforcing these provisions on the Commissioner of Labor. After petitioner Livadas's employer refused to pay her the wages owed upon her discharge, but paid them a few days later, she filed a penalty claim. The Commissioner …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"McDonald v. City of West Branch","cite":"466 U.S. 284","y":1984,"id":"1983/83-219","sc":1,"op":8,"ar":1,"sum":"In a § 1983 action, a federal court should not afford res judicata or collateral estoppel effect to an award in an arbitration proceeding brought pursuant to the terms of a collective-bargaining agreement, and hence petitioner's § 1983 action was not barred by the arbitration award.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 13, 14"}},{"t":"case","label":"Metropolitan Edison Co. v. NLRB","cite":"460 U.S. 693","y":1983,"id":"1982/81-1664","sc":1,"sum":"In the absence of an explicit contractual duty, the imposition of more severe sanctions on union officials than on other employees for participating in an unlawful work stoppage violates § 8(a)(3).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Mitsubishi Motors Corp. v. Soler Chrysler-Plym- outh, Inc.","cite":"473 U.S. 614","y":1985,"id":"1984/83-1569","sc":1,"op":9,"sum":"The Supreme Court held that claims arising under the Sherman Act and encompassed in a valid arbitration clause in an international commercial transaction are arbitrable under the federal Arbitration Act. Justice John Paul Stevens dissented, arguing that a fair construction of the arbitration clause does not encompass antitrust claims.","sumSrc":"Oyez","by":{"0":"8, 15, 19, 22, 24, 25"}},{"t":"case","label":"NCAA v. Smith","cite":"525 U.S. 459","y":1999,"id":"1998/98-84","sc":1,"op":6,"sum":"The Court held that dues payments from recipients of federal funds do not suffice to subject the NCAA to suit under Title IX.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"NLRB v. Magnavox Co.","cite":"415 U.S. 322","y":1974,"id":"1973/72-1637","sc":1,"op":15,"sum":"At the time respondent company entered into a collective-bargaining agreement with a union, respondent had a blanket rule against distribution by employees of literature on' company property. The collective agreement and subsequent contracts authorized the company to issue fair and nondiscriminatory rules for maintaining orderly conditions on plant property and also provided for bulletin boards for union notices. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Preston v. Ferrer","cite":"128 S. Ct. 978","y":2008,"id":"2007/06-1463","sc":1,"sum":"The Court disagreed with the California Labor Commissioner's assessment and allowed the arbitration to continue. Justice Ruth Bader Ginsburg, writing for an 8-1 majority, stated that the California law granting exclusive jurisdiction to the Labor Commission was superseded by the Federal Arbitration Act because the parties to this case had agreed to arbitrate any contractual disputes.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Pryner v. Tractor Supply Co.","cite":"109 F.3d 354","y":1997,"url":"https://www.courtlistener.com/c/F.3d/109/354/","by":{"0":"26"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/Am. Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"op":5,"sum":"Noting Wilko’s reliance on “the outmoded pre­ sumption of disfavoring arbitration proceedings”.","sumSrc":"opinion","by":{"0":"15"}},{"t":"case","label":"Shearson/Am. Express Inc. v. McMahon","cite":"482 U.S. 220","y":1987,"id":"1986/86-44","sc":1,"op":3,"sum":"Respondents were customers of petitioner Shearson/American Express Inc. (Shearson), a brokerage firm registered with the Securities and Exchange Commission (SEC), under customer agreements providing for arbitration of any controversy relating to their accounts. Respondents filed suit in Federal District Court against Shearson and its representative (also a petitioner here) who handled their accounts, alleging …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Smart v. International Bhd. of Elec. Workers, Local 702","cite":"315 F.3d 721","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/315/721/","sum":"Holding that both the FAA and Section 301 apply to CBAs.","sumSrc":"brief:0","by":{"0":"22"}},{"t":"case","label":"Textile Workers Union v. Lincoln Mills","cite":"353 U.S. 448","y":1957,"id":"1956/211","sc":1,"op":1,"sum":"A union entered into a collective-bargaining agreement with an employer providing that there would be no strikes or work stoppages and that grievances would be handled pursuant to a specified procedure, the last step of which was arbitration. Grievances arose and were processed through various steps in the grievance procedure until the union's demands were finally denied by the employer. The union requested …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"United Paperworkers Int’l Union v. Misco, Inc.","cite":"484 U.S. 29","y":1987,"id":"1987/86-651","sc":1,"sum":"Respondent employer's collective-bargaining agreement with petitioner union authorizes the submission to binding arbitration of any grievance that arises from the interpretation or application of the agreement's terms, and reserves to management the right to establish, amend, and enforce rules regulating employee discharge and discipline and setting forth disciplinary procedures. One of respondent's rules listed as …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Case—Continued: Wright v. Universal Maritime Serv. Corp.","cite":"525 U.S. 70","y":1998,"id":"1998/97-889","sc":1,"op":9,"ar":1,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the CBA's arbitration clause did not require Wright to use the arbitration procedure for the alleged violation of the ADA. In his opinion, Scalia wrote that the CBA did not contain a waiver of the employee's right to a judicial forum for federal claims of employment discrimination.","sumSrc":"Oyez","by":{"0":"2, 6, 15, 20, 23"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","stext":{"head":"§621. Congressional statement of findings and purpose","paras":[[0,"(a) The Congress hereby finds and declares that—"],[1,"(1) in the face of rising productivity and affluence, older workers find themselves disadvantaged in their efforts to retain employment, and especially to regain employment when displaced from jobs;"],[1,"(2) the setting of arbitrary age limits regardless of potential for job performance has become a common practice, and certain otherwise desirable practices may work to the disadvantage of older persons;"],[1,"(3) the incidence of unemployment, especially long-term unemployment with resultant deterioration of skill, morale, and employer acceptability is, relative to the younger ages, high among older workers; their numbers are great and growing; and their employment problems grave;"],[1,"(4) the existence in industries affecting commerce, of arbitrary discrimination in employment because of age, burdens commerce and the free flow of goods in commerce."],[0,"(b) It is therefore the purpose of this chapter to promote employment of older persons based on their ability rather than age; to prohibit arbitrary age discrimination in employment; to help employers and workers find ways of meeting problems arising from the impact of age on employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/621?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§621. Congressional statement of findings and purpose","tname":"Labor","by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(b)","(c)(1)","(f)(1)","(f)(1)(A)","(f)(1)(C)","(f)(1)(D)"],"stext":{"head":"§626. Recordkeeping, investigation, and enforcement","paras":[[0,"(a) Attendance of witnesses; investigations, inspections, records, and homework regulations"],[0,"The Equal Employment Opportunity Commission shall have the power to make investigations and require the keeping of records necessary or appropriate for the administration of this chapter in accordance with the powers and procedures provided in sections 209 and 211 of this title."],[0,"(b) Enforcement; prohibition of age discrimination under fair labor standards; unpaid minimum wages and unpaid overtime compensation; liquidated damages; judicial relief; conciliation, conference, and persuasion"],[0,"The provisions of this chapter shall be enforced in accordance with the powers, remedies, and procedures provided in sections 211(b), 216 (except for subsection (a) thereof), and 217 of this title, and subsection (c) of this section. Any act prohibited under section 623 of this title shall be deemed to be a prohibited act under section 215 of this title. Amounts owing to a person as a result of a violation of this chapter shall be deemed to be unpaid minimum wages or unpaid overtime compensation for purposes of sections 216 and 217 of this title: Provided, That liquidated damages shall be payable only in cases of willful violations of this chapter. In any action brought to enforce this chapter the court shall have jurisdiction to grant such legal or equitable relief as may be appropriate to effectuate the purposes of this chapter, including without limitation judgments compelling employment, reinstatement or promotion, or enforcing the liability for amounts deemed to be unpaid minimum wages or unpaid overtime compensation under this section. Before instituting any action under this section, the Equal Employment Opportunity Commission shall attempt to eliminate the discriminatory practice or practices alleged, and to effect voluntary compliance with the requirements of this chapter through informal methods of conciliation, conference, and persuasion."],[0,"(c) Civil actions; persons aggrieved; jurisdiction; judicial relief; termination of individual action upon commencement of action by Commission; jury trial"],[0,"(1) Any person aggrieved may bring a civil action in any court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter: Provided, That the right of any person to bring such action shall terminate upon the commencement of an action by the Equal Employment Opportunity Commission to enforce the right of such employee under this chapter."],[0,"(2) In an action brought under paragraph (1), a person shall be entitled to a trial by jury of any issue of fact in any such action for recovery of amounts owing as a result of a violation of this chapter, regardless of whether equitable relief is sought by any party in such action."],[0,"(d) Filing of charge with Commission; timeliness; conciliation, conference, and persuasion; unlawful practice"],[0,"(1) No civil action may be commenced by an individual under this section until 60 days after a charge alleging unlawful discrimination has been filed with the Equal Employment Opportunity Commission. Such a charge shall be filed—"],[1,"(A) within 180 days after the alleged unlawful practice occurred; or"],[1,"(B) in a case to which section 633(b) of this title applies, within 300 days after the alleged unlawful practice occurred, or within 30 days after receipt by the individual of notice of termination of proceedings under State law, whichever is earlier."],[0,"(2) Upon receiving such a charge, the Commission shall promptly notify all persons named in such charge as prospective defendants in the action and shall promptly seek to eliminate any alleged unlawful practice by informal methods of conciliation, conference, and persuasion."],[0,"(3) For purposes of this section, an unlawful practice occurs, with respect to discrimination in compensation in violation of this chapter, when a discriminatory compensation decision or other practice is adopted, when a person becomes subject to a discriminatory compensation decision or other practice, or when a person is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(e) Reliance on administrative rulings; notice of dismissal or termination; civil action after receipt of notice"],[0,"Section 259 of this title shall apply to actions under this chapter. If a charge filed with the Commission under this chapter is dismissed or the proceedings of the Commission are otherwise terminated by the Commission, the Commission shall notify the person aggrieved. A civil action may be brought under this section by a person defined in section 630(a) of this title against the respondent named in the charge within 90 days after the date of the receipt of such notice."],[0,"(f) Waiver"],[0,"(1) An individual may not waive any right or claim under this chapter unless the waiver is knowing and voluntary. Except as provided in paragraph (2), a waiver may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) the waiver is part of an agreement between the individual and the employer that is written in a manner calculated to be understood by such individual, or by the average individual eligible to participate;"],[1,"(B) the waiver specifically refers to rights or claims arising under this chapter;"],[1,"(C) the individual does not waive rights or claims that may arise after the date the waiver is executed;"],[1,"(D) the individual waives rights or claims only in exchange for consideration in addition to anything of value to which the individual already is entitled;"],[1,"(E) the individual is advised in writing to consult with an attorney prior to executing the agreement;"],[1,"(F)(i) the individual is given a period of at least 21 days within which to consider the agreement; or"],[1,"(ii) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the individual is given a period of at least 45 days within which to consider the agreement;"],[1,"(G) the agreement provides that for a period of at least 7 days following the execution of such agreement, the individual may revoke the agreement, and the agreement shall not become effective or enforceable until the revocation period has expired;"],[1,"(H) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the employer (at the commencement of the period specified in subparagraph (F)) informs the individual in writing in a manner calculated to be understood by the average individual eligible to participate, as to—"],[2,"(i) any class, unit, or group of individuals covered by such program, any eligibility factors for such program, and any time limits applicable to such program; and"],[2,"(ii) the job titles and ages of all individuals eligible or selected for the program, and the ages of all individuals in the same job classification or organizational unit who are not eligible or selected for the program."],[0,"(2) A waiver in settlement of a charge filed with the Equal Employment Opportunity Commission, or an action filed in court by the individual or the individual's representative, alleging age discrimination of a kind prohibited under section 623 or 633a of this title may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) subparagraphs (A) through (E) of paragraph (1) have been met; and"],[1,"(B) the individual is given a reasonable period of time within which to consider the settlement agreement."],[0,"(3) In any dispute that may arise over whether any of the requirements, conditions, and circumstances set forth in subparagraph (A), (B), (C), (D), (E), (F), (G), or (H) of paragraph (1), or subparagraph (A) or (B) of paragraph (2), have been met, the party asserting the validity of a waiver shall have the burden of proving in a court of competent jurisdiction that a waiver was knowing and voluntary pursuant to paragraph (1) or (2)."],[0,"(4) No waiver agreement may affect the Commission's rights and responsibilities to enforce this chapter. No waiver may be used to justify interfering with the protected right of an employee to file a charge or participate in an investigation or proceeding conducted by the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/626?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§626. Recordkeeping, investigation, and enforcement","tname":"Labor","by":{"0":"2, 12, 12, 8, 19, 19, 27, 19, 19"}},{"t":"usc","label":"29 U.S.C. § 633a","url":"https://www.law.cornell.edu/uscode/text/29/633a","by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 12117","url":"https://www.law.cornell.edu/uscode/text/42/12117","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 12212","url":"https://www.law.cornell.edu/uscode/text/42/12212","by":{"0":"25, 26"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"1, 2, 6, 11, 13, 17, 25"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(a)"],"by":{"0":"2, 2"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","stext":{"head":"§1981. Equal rights under the law","paras":[[0,"(a) Statement of equal rights"],[0,"All persons within the jurisdiction of the United States shall have the same right in every State and Territory to make and enforce contracts, to sue, be parties, give evidence, and to the full and equal benefit of all laws and proceedings for the security of persons and property as is enjoyed by white citizens, and shall be subject to like punishment, pains, penalties, taxes, licenses, and exactions of every kind, and to no other."],[0,"(b) \"Make and enforce contracts\" defined"],[0,"For purposes of this section, the term \"make and enforce contracts\" includes the making, performance, modification, and termination of contracts, and the enjoyment of all benefits, privileges, terms, and conditions of the contractual relationship."],[0,"(c) Protection against impairment"],[0,"The rights protected by this section are protected against impairment by nongovernmental discrimination and impairment under color of State law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1981?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1981. Equal rights under the law","tname":"The Public Health and Welfare","by":{"0":"9, 25, 27, 25"}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","subs":["(d)"],"by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"0":"14"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(c)"],"by":{"0":"2"}},{"t":"usc","label":"9 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/9/1","by":{"0":"22, 22"}},{"t":"usc","label":"9 U.S.C. § 3","url":"https://www.law.cornell.edu/uscode/text/9/3","stext":{"head":"§3. Stay of proceedings where issue therein referable to arbitration","paras":[[0,"If any suit or proceeding be brought in any of the courts of the United States upon any issue referable to arbitration under an agreement in writing for such arbitration, the court in which such suit is pending, upon being satisfied that the issue involved in such suit or proceeding is referable to arbitration under such an agreement, shall on application of one of the parties stay the trial of the action until such arbitration has been had in accordance with the terms of the agreement, providing the applicant for the stay is not in default in proceeding with such arbitration."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/9/3?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3. Stay of proceedings where issue therein referable to arbitration","tname":"Arbitration","by":{"0":"5"}},{"t":"usc","label":"9 U.S.C. § 4","url":"https://www.law.cornell.edu/uscode/text/9/4","stext":{"head":"§4. Failure to arbitrate under agreement; petition to United States court having jurisdiction for order to compel arbitration; notice and service thereof; hearing and determination","paras":[[0,"A party aggrieved by the alleged failure, neglect, or refusal of another to arbitrate under a written agreement for arbitration may petition any United States district court which, save for such agreement, would have jurisdiction under title 28, in a civil action or in admiralty of the subject matter of a suit arising out of the controversy between the parties, for an order directing that such arbitration proceed in the manner provided for in such agreement. Five days' notice in writing of such application shall be served upon the party in default. Service thereof shall be made in the manner provided by the Federal Rules of Civil Procedure. The court shall hear the parties, and upon being satisfied that the making of the agreement for arbitration or the failure to comply therewith is not in issue, the court shall make an order directing the parties to proceed to arbitration in accordance with the terms of the agreement. The hearing and proceedings, under such agreement, shall be within the district in which the petition for an order directing such arbitration is filed. If the making of the arbitration agreement or the failure, neglect, or refusal to perform the same be in issue, the court shall proceed summarily to the trial thereof. If no jury trial be demanded by the party alleged to be in default, or if the matter in dispute is within admiralty jurisdiction, the court shall hear and determine such issue. Where such an issue is raised, the party alleged to be in default may, except in cases of admiralty, on or before the return day of the notice of application, demand a jury trial of such issue, and upon such demand the court shall make an order referring the issue or issues to a jury in the manner provided by the Federal Rules of Civil Procedure, or may specially call a jury for that purpose. If the jury find that no agreement in writing for arbitration was made or that there is no default in proceeding thereunder, the proceeding shall be dismissed. If the jury find that an agreement for arbitration was made in writing and that there is a default in proceeding thereunder, the court shall make an order summarily directing the parties to proceed with the arbitration in accordance with the terms thereof."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/9/4?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4. Failure to arbitrate under agreement; petition to United States court having jurisdiction for order to compel arbitration; notice and service thereof; hearing and determination","tname":"Arbitration","by":{"0":"5"}},{"t":"usc","label":"29 U.S.C. § 185","url":"https://www.law.cornell.edu/uscode/text/29/185","stext":{"head":"§185. Suits by and against labor organizations","paras":[[0,"(a) Venue, amount, and citizenship"],[0,"Suits for violation of contracts between an employer and a labor organization representing employees in an industry affecting commerce as defined in this chapter, or between any such labor organizations, may be brought in any district court of the United States having jurisdiction of the parties, without respect to the amount in controversy or without regard to the citizenship of the parties."],[0,"(b) Responsibility for acts of agent; entity for purposes of suit; enforcement of money judgments"],[0,"Any labor organization which represents employees in an industry affecting commerce as defined in this chapter and any employer whose activities affect commerce as defined in this chapter shall be bound by the acts of its agents. Any such labor organization may sue or be sued as an entity and in behalf of the employees whom it represents in the courts of the United States. Any money judgment against a labor organization in a district court of the United States shall be enforceable only against the organization as an entity and against its assets, and shall not be enforceable against any individual member or his assets."],[0,"(c) Jurisdiction"],[0,"For the purposes of actions and proceedings by or against labor organizations in the district courts of the United States, district courts shall be deemed to have jurisdiction of a labor organization (1) in the district in which such organization maintains its principal office, or (2) in any district in which its duly authorized officers or agents are engaged in representing or acting for employee members."],[0,"(d) Service of process"],[0,"The service of summons, subpena, or other legal process of any court of the United States upon an officer or agent of a labor organization, in his capacity as such, shall constitute service upon the labor organization."],[0,"(e) Determination of question of agency"],[0,"For the purposes of this section, in determining whether any person is acting as an \"agent\" of another person so as to make such other person responsible for his acts, the question of whether the specific acts performed were actually authorized or subsequently ratified shall not be controlling."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/185?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§185. Suits by and against labor organizations","tname":"Labor","by":{"0":"22, 23"}},{"t":"usc","label":"29 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/29/151","stext":{"head":"§151. Findings and declaration of policy","paras":[[0,"The denial by some employers of the right of employees to organize and the refusal by some employers to accept the procedure of collective bargaining lead to strikes and other forms of industrial strife or unrest, which have the intent or the necessary effect of burdening or obstructing commerce by (a) impairing the efficiency, safety, or operation of the instrumentalities of commerce; (b) occurring in the current of commerce; (c) materially affecting, restraining, or controlling the flow of raw materials or manufactured or processed goods from or into the channels of commerce, or the prices of such materials or goods in commerce; or (d) causing diminution of employment and wages in such volume as substantially to impair or disrupt the market for goods flowing from or into the channels of commerce."],[0,"The inequality of bargaining power between employees who do not possess full freedom of association or actual liberty of contract, and employers who are organized in the corporate or other forms of ownership association substantially burdens and affects the flow of commerce, and tends to aggravate recurrent business depressions, by depressing wage rates and the purchasing power of wage earners in industry and by preventing the stabilization of competitive wage rates and working conditions within and between industries."],[0,"Experience has proved that protection by law of the right of employees to organize and bargain collectively safeguards commerce from injury, impairment, or interruption, and promotes the flow of commerce by removing certain recognized sources of industrial strife and unrest, by encouraging practices fundamental to the friendly adjustment of industrial disputes arising out of differences as to wages, hours, or other working conditions, and by restoring equality of bargaining power between employers and employees."],[0,"Experience has further demonstrated that certain practices by some labor organizations, their officers, and members have the intent or the necessary effect of burdening or obstructing commerce by preventing the free flow of goods in such commerce through strikes and other forms of industrial unrest or through concerted activities which impair the interest of the public in the free flow of such commerce. The elimination of such practices is a necessary condition to the assurance of the rights herein guaranteed."],[0,"It is hereby declared to be the policy of the United States to eliminate the causes of certain substantial obstructions to the free flow of commerce and to mitigate and eliminate these obstructions when they have occurred by encouraging the practice and procedure of collective bargaining and by protecting the exercise by workers of full freedom of association, self-organization, and designation of representatives of their own choosing, for the purpose of negotiating the terms and conditions of their employment or other mutual aid or protection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/151?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§151. Findings and declaration of policy","tname":"Labor","by":{"0":"16"}},{"t":"usc","label":"29 U.S.C. § 159","url":"https://www.law.cornell.edu/uscode/text/29/159","subs":["(a)"],"stext":{"head":"§159. Representatives and elections","paras":[[0,"(a) Exclusive representatives; employees' adjustment of grievances directly with employer"],[0,"Representatives designated or selected for the purposes of collective bargaining by the majority of the employees in a unit appropriate for such purposes, shall be the exclusive representatives of all the employees in such unit for the purposes of collective bargaining in respect to rates of pay, wages, hours of employment, or other conditions of employment: Provided, That any individual employee or a group of employees shall have the right at any time to present grievances to their employer and to have such grievances adjusted, without the intervention of the bargaining representative, as long as the adjustment is not inconsistent with the terms of a collective-bargaining contract or agreement then in effect: Provided further, That the bargaining representative has been given opportunity to be present at such adjustment."],[0,"(b) Determination of bargaining unit by Board"],[0,"The Board shall decide in each case whether, in order to assure to employees the fullest freedom in exercising the rights guaranteed by this subchapter, the unit appropriate for the purposes of collective bargaining shall be the employer unit, craft unit, plant unit, or subdivision thereof: Provided, That the Board shall not (1) decide that any unit is appropriate for such purposes if such unit includes both professional employees and employees who are not professional employees unless a majority of such professional employees vote for inclusion in such unit; or (2) decide that any craft unit is inappropriate for such purposes on the ground that a different unit has been established by a prior Board determination, unless a majority of the employees in the proposed craft unit vote against separate representation or (3) decide that any unit is appropriate for such purposes if it includes, together with other employees, any individual employed as a guard to enforce against employees and other persons rules to protect property of the employer or to protect the safety of persons on the employer's premises; but no labor organization shall be certified as the representative of employees in a bargaining unit of guards if such organization admits to membership, or is affiliated directly or indirectly with an organization which admits to membership, employees other than guards."],[0,"(c) Hearings on questions affecting commerce; rules and regulations"],[0,"(1) Whenever a petition shall have been filed, in accordance with such regulations as may be prescribed by the Board—"],[1,"(A) by an employee or group of employees or any individual or labor organization acting in their behalf alleging that a substantial number of employees (i) wish to be represented for collective bargaining and that their employer declines to recognize their representative as the representative defined in subsection (a), or (ii) assert that the individual or labor organization, which has been certified or is being currently recognized by their employer as the bargaining representative, is no longer a representative as defined in subsection (a); or"],[1,"(B) by an employer, alleging that one or more individuals or labor organizations have presented to him a claim to be recognized as the representative defined in subsection (a);"],[0,"the Board shall investigate such petition and if it has reasonable cause to believe that a question of representation affecting commerce exists shall provide for an appropriate hearing upon due notice. Such hearing may be conducted by an officer or employee of the regional office, who shall not make any recommendations with respect thereto. If the Board finds upon the record of such hearing that such a question of representation exists, it shall direct an election by secret ballot and shall certify the results thereof."],[0,"(2) In determining whether or not a question of representation affecting commerce exists, the same regulations and rules of decision shall apply irrespective of the identity of the persons filing the petition or the kind of relief sought and in no case shall the Board deny a labor organization a place on the ballot by reason of an order with respect to such labor organization or its predecessor not issued in conformity with section 160(c) of this title."],[0,"(3) No election shall be directed in any bargaining unit or any subdivision within which in the preceding twelve-month period, a valid election shall have been held. Employees engaged in an economic strike who are not entitled to reinstatement shall be eligible to vote under such regulations as the Board shall find are consistent with the purposes and provisions of this subchapter in any election conducted within twelve months after the commencement of the strike. In any election where none of the choices on the ballot receives a majority, a run-off shall be conducted, the ballot providing for a selection between the two choices receiving the largest and second largest number of valid votes cast in the election."],[0,"(4) Nothing in this section shall be construed to prohibit the waiving of hearings by stipulation for the purpose of a consent election in conformity with regulations and rules of decision of the Board."],[0,"(5) In determining whether a unit is appropriate for the purposes specified in subsection (b) the extent to which the employees have organized shall not be controlling."],[0,"(d) Petition for enforcement or review; transcript"],[0,"Whenever an order of the Board made pursuant to section 160(c) of this title is based in whole or in part upon facts certified following an investigation pursuant to subsection (c) of this section and there is a petition for the enforcement or review of such order, such certification and the record of such investigation shall be included in the transcript of the entire record required to be filed under subsection (e) or (f) of section 160 of this title, and thereupon the decree of the court enforcing, modifying, or setting aside in whole or in part the order of the Board shall be made and entered upon the pleadings, testimony, and proceedings set forth in such transcript."],[0,"(e) Secret ballot; limitation of elections"],[0,"(1) Upon the filing with the Board, by 30 per centum or more of the employees in a bargaining unit covered by an agreement between their employer and a labor organization made pursuant to section 158(a)(3) of this title, of a petition alleging they desire that such authority be rescinded, the Board shall take a secret ballot of the employees in such unit and certify the results thereof to such labor organization and to the employer."],[0,"(2) No election shall be conducted pursuant to this subsection in any bargaining unit or any subdivision within which, in the preceding twelve-month period, a valid election shall have been held."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/159?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§159. Representatives and elections","tname":"Labor","by":{"0":"16"}},{"t":"usc","label":"38 U.S.C. § 4301","url":"https://www.law.cornell.edu/uscode/text/38/4301","by":{"0":"1"}},{"t":"usc","label":"38 U.S.C. § 4323","url":"https://www.law.cornell.edu/uscode/text/38/4323","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"9 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/9/16","subs":["(a)(1)"],"stext":{"head":"§16. Appeals","paras":[[0,"(a) An appeal may be taken from—"],[1,"(1) an order—"],[2,"(A) refusing a stay of any action under section 3 of this title,"],[2,"(B) denying a petition under section 4 of this title to order arbitration to proceed,"],[2,"(C) denying an application under section 206 of this title to compel arbitration,"],[2,"(D) confirming or denying confirmation of an award or partial award, or"],[2,"(E) modifying, correcting, or vacating an award;"],[1,"(2) an interlocutory order granting, continuing, or modifying an injunction against an arbitration that is subject to this title; or"],[1,"(3) a final decision with respect to an arbitration that is subject to this title."],[0,"(b) Except as otherwise provided in section 1292(b) of title 28, an appeal may not be taken from an interlocutory order—"],[1,"(1) granting a stay of any action under section 3 of this title;"],[1,"(2) directing arbitration to proceed under section 4 of this title;"],[1,"(3) compelling arbitration under section 206 of this title; or"],[1,"(4) refusing to enjoin an arbitration that is subject to this title."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/9/16?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§16. Appeals","tname":"Arbitration","by":{"0":"6, 23"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"13, 17"}}]};